/*
 * ============================================================================
 * TINYPHASENET v2 (1 CHANNEL Z) - HARDWARE PROFILING, full INT8 or 16x8 variant
 * (build env `int8` / `16x8` in platformio.ini; macro MODEL_16X8)
 * Target: ESP32-S3 DevKitC-1 N8 @ 240 MHz + INA219 (SDA 17, SCL 18)
 *
 * - Input: 100 test windows (50 earthquake + 50 noise) from STEAD, INSTANCE, or ETHZ
 *   (include/hw_eval_<dataset>.h, generated by 10_make_hw_eval_inputs.py; selected through the
 *   build flag HW_DATASET_*). The 1-45 Hz band-pass, z-score, and input quantization run on the device.
 * - The tensor arena is allocated from the largest internal heap block (the 16x8 variant needs an
 *   arena about 2x larger than full INT8).
 * - Detection score = maximum P probability over the 3072 samples (same as in Python).
 *   The score is matched against the TFLite score in Python (PY_SCORES) to validate the port.
 * - Power: the INA219 is sampled from core 0 WHILE Invoke() runs on core 1.
 *   Idle power is measured separately as a reference.
 * ============================================================================
 */

// Main profiling program; env `debug16` uses src/debug_stages.cpp and env `stalta`
// uses src/stalta_profiling.cpp instead.
#if !defined(DEBUG_STAGES) && !defined(STALTA_PROFILING) && !defined(SEISMICSENSE_PROFILING) && !defined(CASCADE_PROFILING) && !defined(ONDEVICE_LEARNING_PROFILING) && !defined(FLASH_UPDATE_PROFILING) && !defined(STREAM_LEARNING) && !defined(MODEL_3CH_16X8) && !defined(OP_PROFILE) && !defined(FP32_1CH) && !defined(FP32_3CH) && !defined(STAT_BENCH)
#include <math.h>
#include <Wire.h>
#include <Adafruit_INA219.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/schema/schema_generated.h"
#include "soc/rtc_cntl_reg.h"
#include "esp_heap_caps.h"

// TRANSPOSE_CONV kernel with the fused-activation fix (src/transpose_conv_act_fix.cc).
namespace tflite { TFLMRegistration Register_TRANSPOSE_CONV_ACT_FIX(); }

#include "hw_eval.h"
#ifdef MODEL_16X8
#include "tinyphasenet_16x8_model.h"
typedef int16_t q_t;
static const TfLiteType kQType = kTfLiteInt16;
static const char* kVariant = "16x8 (aktivasi int16, bobot int8)";
static const float THRESHOLD = HW_THR_16X8;
static const float* PY_SCORES = HW_PY_16X8;
#else
#include "tinyphasenet_int8_model.h"
typedef int8_t q_t;
static const TfLiteType kQType = kTfLiteInt8;
static const char* kVariant = "INT8 penuh";
static const float THRESHOLD = HW_THR_INT8;
static const float* PY_SCORES = HW_PY_INT8;
#endif
static const int32_t kQMin = sizeof(q_t) == 1 ? -128 : -32768;
static const int32_t kQMax = sizeof(q_t) == 1 ? 127 : 32767;

Adafruit_INA219 ina219;

static uint8_t* tensor_arena = nullptr;
static size_t tensor_arena_size = 0;

static const tflite::Model* tflite_model = nullptr;
static tflite::MicroInterpreter* interpreter = nullptr;
static TfLiteTensor* model_input = nullptr;
static TfLiteTensor* model_output = nullptr;

constexpr int WARMUP_REPS = 5;
constexpr int MEASURE_REPS = 2 * HW_N;   // two passes; the accuracy comes from the first pass
constexpr int IDLE_MS = 3000;

static float invoke_ms[MEASURE_REPS];
static float preprocess_ms[MEASURE_REPS];
static float filter_ms[MEASURE_REPS];

// --- Sampler daya (core 0) ---
enum Phase : int { PHASE_NONE = 0, PHASE_IDLE = 1, PHASE_ACTIVE = 2 };
static volatile int g_phase = PHASE_NONE;
static volatile bool g_sampler_run = true;
static volatile double g_sum_mW[3] = {0, 0, 0};
static volatile uint32_t g_n[3] = {0, 0, 0};

void powerSamplerTask(void*) {
  while (g_sampler_run) {
    int before = g_phase;
    float p = ina219.getPower_mW();
    int after = g_phase;
    if (before == after && before != PHASE_NONE) {  // drop samples that cross a phase boundary
      g_sum_mW[before] += p;
      g_n[before]++;
    }
    vTaskDelay(1);  // beri giliran IDLE0 (task watchdog); FreeRTOS 1000 Hz
  }
  vTaskDelete(NULL);
}

void computeStats(const float* d, int n, float* mean, float* sd, float* mn, float* mx) {
  double s = 0, s2 = 0;
  *mn = d[0]; *mx = d[0];
  for (int i = 0; i < n; i++) {
    s += d[i]; s2 += (double)d[i] * d[i];
    if (d[i] < *mn) *mn = d[i];
    if (d[i] > *mx) *mx = d[i];
  }
  double m = s / n, v = s2 / n - m * m;
  *mean = (float)m;
  *sd = (float)(v > 0 ? sqrt(v) : 0.0);
}

// Z-score of the raw window, then quantization into the input tensor (round + clamp).
// Causal 1-45 Hz band-pass (SOS, direct form II transposed as in scipy sosfilt) run from the
// start of the trace to the end of the test window, equivalent to the Python preprocessing (data.prefilter). The time
// to filter the 3072 samples of the test window is recorded separately (streaming cost per window).
static float g_filter_window_us = 0;
void loadWindow(int w) {
  static float x[HW_WINDOW];
  float zi[HW_PRE_NSOS][2] = {};
  const int st = HW_EVAL_START[w];
  unsigned long tf0 = 0;
  for (int i = 0; i < st + HW_WINDOW; i++) {
    if (i == st) tf0 = micros();
    float v = hwSample(w, i) - HW_MEAN[w];
    for (int s = 0; s < HW_PRE_NSOS; s++) {
      const float* c = HW_PRE_SOS[s];
      float y = c[0] * v + zi[s][0];
      zi[s][0] = c[1] * v - c[4] * y + zi[s][1];
      zi[s][1] = c[2] * v - c[5] * y;
      v = y;
    }
    if (i >= st) x[i - st] = v;
  }
  g_filter_window_us = (float)(micros() - tf0);
  double s = 0, s2 = 0;
  for (int i = 0; i < HW_WINDOW; i++) { s += x[i]; s2 += (double)x[i] * x[i]; }
  double mean = s / HW_WINDOW;
  double var = s2 / HW_WINDOW - mean * mean;
  float inv_std = 1.0f / ((float)sqrt(var > 0 ? var : 0) + 1e-8f);
  const float scale = model_input->params.scale;
  const int zp = model_input->params.zero_point;
  q_t* in = reinterpret_cast<q_t*>(model_input->data.raw);
  for (int i = 0; i < HW_WINDOW; i++) {
    float v = ((float)(x[i] - mean)) * inv_std;
    int32_t q = (int32_t)lroundf(v / scale) + zp;
    in[i] = (q_t)(q < kQMin ? kQMin : (q > kQMax ? kQMax : q));
  }
}

// Maximum P probability over the window. Output [1, WINDOW_LEN, 3] = (P, S, Noise).
float maxPScore() {
  const int c = model_output->dims->data[model_output->dims->size - 1];
  const int steps = model_output->dims->data[model_output->dims->size - 2];
  const float s = model_output->params.scale;
  const int zp = model_output->params.zero_point;
  const q_t* o = reinterpret_cast<const q_t*>(model_output->data.raw);
  q_t best = (q_t)kQMin;
  for (int t = 0; t < steps; t++) {
    q_t v = o[t * c];
    if (v > best) best = v;
  }
  return (best - zp) * s;
}

// Port diagnostics: mean of each output channel and sum of the softmax per time sample
// for the first window, to compare with the TFLite interpreter in Python.
void printOutputDiagnostics(int w, float score) {
  const int c = model_output->dims->data[model_output->dims->size - 1];
  const int steps = model_output->dims->data[model_output->dims->size - 2];
  const float sc = model_output->params.scale;
  const int zp = model_output->params.zero_point;
  const q_t* o = reinterpret_cast<const q_t*>(model_output->data.raw);
  double mean[3] = {0, 0, 0}, sum_min = 1e9, sum_max = -1e9;
  for (int t = 0; t < steps; t++) {
    double s = 0;
    for (int k = 0; k < c && k < 3; k++) {
      double v = (o[t * c + k] - zp) * sc;
      mean[k] += v / steps;
      s += v;
    }
    if (s < sum_min) sum_min = s;
    if (s > sum_max) sum_max = s;
  }
  Serial.printf("[DIAG] jendela %d: skor %.6f (Python %.6f) | rata-rata P %.6f S %.6f N %.6f | jumlah softmax [%.4f, %.4f]\n",
                w, score, PY_SCORES[w], mean[0], mean[1], mean[2], sum_min, sum_max);
  Serial.printf("[DIAG] output t=0..3 (raw): %d %d %d | %d %d %d | %d %d %d | %d %d %d\n",
                o[0], o[1], o[2], o[3], o[4], o[5], o[6], o[7], o[8], o[9], o[10], o[11]);
}

void profilingTask(void*) {
  // 1) Daya idle (CPU menunggu, tanpa inferensi)
  g_phase = PHASE_IDLE;
  vTaskDelay(pdMS_TO_TICKS(IDLE_MS));
  g_phase = PHASE_NONE;

  uint32_t tp = 0, tn = 0, fp = 0, fn = 0;
  float max_abs_diff = 0.0f;
  int mismatched_decisions = 0;

  for (int r = -WARMUP_REPS; r < MEASURE_REPS; r++) {
    const int w = (r + WARMUP_REPS) % HW_N;

    unsigned long t0 = micros();
    loadWindow(w);
    unsigned long t1 = micros();

    if (r >= 0) g_phase = PHASE_ACTIVE;
    unsigned long t2 = micros();
    TfLiteStatus st = interpreter->Invoke();
    unsigned long t3 = micros();
    g_phase = PHASE_NONE;

    if (st != kTfLiteOk) {
      Serial.println("[ERROR] Invoke() gagal");
      break;
    }
    const float score = maxPScore();
    if (r == -WARMUP_REPS) printOutputDiagnostics(w, score);
#ifdef PRINT_HASH
    if (r >= 0 && r < HW_N) { TfLiteTensor* o__ = interpreter->output(0); uint32_t h__ = 2166136261u; const uint8_t* d__ = (const uint8_t*)o__->data.raw; for (size_t i__ = 0; i__ < o__->bytes; i__++) { h__ ^= d__[i__]; h__ *= 16777619u; } Serial.printf("HASH %d %08x\n", w, (unsigned)h__); }
#endif
    if (r < 0) continue;

    preprocess_ms[r] = (t1 - t0) / 1000.0f;
    filter_ms[r] = g_filter_window_us / 1000.0f;
    invoke_ms[r] = (t3 - t2) / 1000.0f;

    const bool pred = score >= THRESHOLD;
    const bool label = HW_LABELS[w] == 1;
#ifdef PRINT_SCORES
    if (r < HW_N) Serial.printf("SKOR %d %.6f %.6f %d\n", w, score, PY_SCORES[w], (int)HW_LABELS[w]);
#endif
    if (r < HW_N) {   // accuracy: one pass over the 100 windows
      if (pred && label) tp++;
      else if (!pred && !label) tn++;
      else if (pred && !label) fp++;
      else fn++;
    }

    float diff = fabsf(score - PY_SCORES[w]);
    if (diff > max_abs_diff) max_abs_diff = diff;
    if (pred != (PY_SCORES[w] >= THRESHOLD)) mismatched_decisions++;

    if ((r + 1) % 50 == 0) Serial.printf("[INFO] %d / %d repetisi selesai...\n", r + 1, MEASURE_REPS);
    vTaskDelay(pdMS_TO_TICKS(10));
  }
  g_sampler_run = false;

  float im, isd, imn, imx, pm, psd, pmn, pmx;
  computeStats(invoke_ms, MEASURE_REPS, &im, &isd, &imn, &imx);
  computeStats(preprocess_ms, MEASURE_REPS, &pm, &psd, &pmn, &pmx);
  float fm, fsd, fmn, fmx;
  computeStats(filter_ms, MEASURE_REPS, &fm, &fsd, &fmn, &fmx);
  const double idle_mW = g_n[PHASE_IDLE] ? g_sum_mW[PHASE_IDLE] / g_n[PHASE_IDLE] : 0.0;
  const double active_mW = g_n[PHASE_ACTIVE] ? g_sum_mW[PHASE_ACTIVE] / g_n[PHASE_ACTIVE] : 0.0;

  Serial.println("\n=======================================================");
  Serial.printf(" LAPORAN PROFILING PHASENET-Z v2 (N = %d, %d jendela uji %s)\n", MEASURE_REPS, HW_N, HW_DATASET);
  Serial.printf(" Varian                         | %s\n", kVariant);
  Serial.println("-------------------------------------------------------");
  Serial.printf(" CPU freq (MHz)                 | %d\n", getCpuFrequencyMhz());
  Serial.printf(" Ukuran model (byte)            | %u\n", g_model_len);
  Serial.printf(" Tensor arena terpakai (KB)     | %.3f (dialokasikan %.1f)\n", interpreter->arena_used_bytes() / 1024.0, tensor_arena_size / 1024.0);
  Serial.printf(" Latensi Invoke (ms)            | %.3f +- %.3f [min %.3f, max %.3f]\n", im, isd, imn, imx);
  Serial.printf(" Latensi prapemrosesan total (ms)| %.3f +- %.3f (filter dari awal trace + z-score + kuantisasi)\n", pm, psd);
  Serial.printf(" Latensi bandpass 3072 sampel (ms)| %.3f +- %.3f\n", fm, fsd);
  Serial.printf(" Daya idle (mW)                 | %.3f  (n = %u sampel)\n", idle_mW, g_n[PHASE_IDLE]);
  Serial.printf(" Daya selama Invoke (mW)        | %.3f  (n = %u sampel)\n", active_mW, g_n[PHASE_ACTIVE]);
  Serial.printf(" Energi per inferensi (mJ)      | %.3f\n", active_mW * im / 1000.0);
  Serial.printf(" Energi di atas idle (mJ)       | %.3f\n", (active_mW - idle_mW) * im / 1000.0);
  Serial.println("-------------------------------------------------------");
  Serial.printf(" VALIDASI PORT (vs TFLite Python)\n");
  Serial.printf("   Selisih skor maksimum        : %.6f\n", max_abs_diff);
  Serial.printf("   Keputusan berbeda            : %d / %d\n", mismatched_decisions, MEASURE_REPS);
  {
    const float prec = tp + fp ? (float)tp / (tp + fp) : 0, rec = tp + fn ? (float)tp / (tp + fn) : 0;
    Serial.printf(" AKURASI DI PERANGKAT (%d jendela %s, ambang %.4f)\n", HW_N, HW_DATASET, THRESHOLD);
    Serial.printf("   TP %u  TN %u  FP %u  FN %u\n", tp, tn, fp, fn);
    Serial.printf("   Precision %.4f  Recall %.4f  F1 %.4f  FPR %.4f\n", prec, rec,
                  prec + rec > 0 ? 2 * prec * rec / (prec + rec) : 0.0f, tn + fp ? (float)fp / (fp + tn) : 0.0f);
  }
  Serial.println("=======================================================");
  Serial.println("[INFO] Profiling selesai. Reset board untuk mengulang.");
  vTaskDelete(NULL);
}

void setup() {
  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0);
  Serial.begin(115200);
  unsigned long t = millis();
  while (!Serial && millis() - t < 3000) delay(10);
  Serial.println("\n[INFO] Inisialisasi Profiling TinyPhaseNet v2...");

  Wire.begin(17, 18);
  Wire.setClock(400000);
  if (!ina219.begin()) {
    Serial.println("[ERROR] INA219 tidak ditemukan! Cek kabel I2C.");
    while (1) delay(10);
  }

  tflite_model = tflite::GetModel(g_model);
  if (tflite_model->version() != TFLITE_SCHEMA_VERSION) {
    Serial.println("[ERROR] Versi skema model tidak cocok.");
    while (1) delay(10);
  }

  // Ops used by TinyPhaseNet after the TFLite conversion (SeparableConv1D -> DepthwiseConv2D +
  // Conv2D, Conv1DTranspose -> TransposeConv, plus Reshape/Concatenation/Softmax). Varian
  // 16x8 also uses QUANTIZE (3x) to align the int16 scales inside the graph.
  static tflite::MicroMutableOpResolver<13> resolver;
  resolver.AddQuantize();
  resolver.AddConv2D();
  resolver.AddDepthwiseConv2D();
  resolver.AddTransposeConv(tflite::Register_TRANSPOSE_CONV_ACT_FIX());
  resolver.AddReshape();
  resolver.AddExpandDims();
  resolver.AddSqueeze();
  resolver.AddConcatenation();
  resolver.AddSoftmax();
  resolver.AddAdd();
  resolver.AddMul();
  resolver.AddRelu();
  resolver.AddStridedSlice();

  // Leave 24 KB of internal heap for the stacks of the two tasks (4 KB + 16 KB) created after this point.
  constexpr size_t kHeapReserve = 24 * 1024;
#ifdef ARENA_PSRAM   // only the correctness test of the 16x8 reference kernel (the int64 scratch does not fit in SRAM)
  tensor_arena_size = 1024 * 1024;
  tensor_arena = (uint8_t*)heap_caps_aligned_alloc(16, tensor_arena_size, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
#else
  tensor_arena_size = (heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT) - kHeapReserve) & ~(size_t)15;
  tensor_arena = (uint8_t*)heap_caps_aligned_alloc(16, tensor_arena_size, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
#endif
  if (tensor_arena == nullptr) {
    Serial.println("[ERROR] Gagal alokasi tensor arena.");
    while (1) delay(10);
  }
  static tflite::MicroInterpreter static_interpreter(tflite_model, resolver, tensor_arena, tensor_arena_size);
  interpreter = &static_interpreter;
  if (interpreter->AllocateTensors() != kTfLiteOk) {
    Serial.println("[ERROR] AllocateTensors() gagal.");
    while (1) delay(10);
  }
  model_input = interpreter->input(0);
  model_output = interpreter->output(0);
  if (model_input->type != kQType || model_output->type != kQType ||
      model_input->bytes != HW_WINDOW * sizeof(q_t)) {
    Serial.println("[ERROR] Tipe/ukuran tensor model tidak sesuai varian build.");
    while (1) delay(10);
  }
  Serial.printf("[INFO] Input scale/zp: %f / %d, output scale/zp: %f / %d\n",
                model_input->params.scale, model_input->params.zero_point,
                model_output->params.scale, model_output->params.zero_point);

  if (xTaskCreatePinnedToCore(powerSamplerTask, "PowerSampler", 4096, NULL, 2, NULL, 0) != pdPASS ||
      xTaskCreatePinnedToCore(profilingTask, "Profiling", 16384, NULL, 1, NULL, 1) != pdPASS) {
    Serial.println("[ERROR] Gagal membuat task (heap tidak cukup).");
    while (1) delay(10);
  }
}

void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }

extern "C" void app_main(void) {
  initArduino();
  setup();
  while (true) loop();
}

#endif  // !DEBUG_STAGES && !STALTA_PROFILING
